  labelOptic = field "lineposition"

-- | Sets the shape and color of the shadow behind text. @auto@ places minimal shadow and applies contrast text font color. See https:\/\/developer.mozilla.org\/en-US\/docs\/Web\/CSS\/text-shadow for additional options. (Default: @\"none\"@.)
instance (k ~ A_Lens, a ~ Maybe (ArrayOk Text), b ~ Maybe (ArrayOk Text)) => LabelOptic "shadow" k (Obj "icicle.textfont") (Obj "icicle.textfont") a b where
  labelOptic = field "shadow"

-- | (Minimum: @1@.)
instance (k ~ A_Lens, a ~ Maybe (ArrayOk Double), b ~ Maybe (ArrayOk Double)) => LabelOptic "size" k (Obj "icicle.textfont") (Obj "icicle.textfont") a b where
  labelOptic = field "size"

-- | Sets whether a font should be styled with a normal or italic face from its family. (Default: @\"normal\"@.)
instance (k ~ A_Lens, a ~ Maybe (ArrayOk Style), b ~ Maybe (ArrayOk Style)) => LabelOptic "style" k (Obj "icicle.textfont") (Obj "icicle.textfont") a b where
  labelOptic = field "style"

-- | Sets capitalization of text. It can be used to make text appear in all-uppercase or all-lowercase, or with each word capitalized. (Default: @\"normal\"@.)
instance (k ~ A_Lens, a ~ Maybe (ArrayOk Textcase), b ~ Maybe (ArrayOk Textcase)) => LabelOptic "textcase" k (Obj "icicle.textfont") (Obj "icicle.textfont") a b where
  labelOptic = field "textcase"

-- | Sets the variant of the font. (Default: @\"normal\"@.)
instance (k ~ A_Lens, a ~ Maybe (ArrayOk Variant), b ~ Maybe (ArrayOk Variant)) => LabelOptic "variant" k (Obj "icicle.textfont") (Obj "icicle.textfont") a b where
  labelOptic = field "variant"

-- | Sets the weight (or boldness) of the font. (Default: @\"normal\"@; Range: @1@ to @1000@.)
instance (k ~ A_Lens, a ~ Maybe (ArrayOk Weight), b ~ Maybe (ArrayOk Weight)) => LabelOptic "weight" k (Obj "icicle.textfont") (Obj "icicle.textfont") a b where
  labelOptic = field "weight"

-- | Determines if the positions obtained from solver are flipped on each axis. (Default: @\"\"@.)
instance (k ~ A_Lens, a ~ Maybe (Flags Flip Void), b ~ Maybe (Flags Flip Void)) => LabelOptic "flip" k (Obj "icicle.tiling") (Obj "icicle.tiling") a b where
  labelOptic = field "flip"

-- | When set in conjunction with @tiling.flip@, determines on which side the root nodes are drawn in the chart. If @tiling.orientation@ is @v@ and @tiling.flip@ is \*\*, the root nodes appear at the top. If @tiling.orientation@ is @v@ and @tiling.flip@ is @y@, the root nodes appear at the bottom. If @tiling.orientation@ is @h@ and @tiling.flip@ is \*\*, the root nodes appear at the left. If @tiling.orientation@ is @h@ and @tiling.flip@ is @x@, the root nodes appear at the right. (Default: @\"h\"@.)
instance (k ~ A_Lens, a ~ Maybe Orientation, b ~ Maybe Orientation) => LabelOptic "orientation" k (Obj "icicle.tiling") (Obj "icicle.tiling") a b where
  labelOptic = field "orientation"

-- | Sets the inner padding (in px). (Default: @0@; Minimum: @0@.)
instance (k ~ A_Lens, a ~ Maybe Double, b ~ Maybe Double) => LabelOptic "pad" k (Obj "icicle.tiling") (Obj "icicle.tiling") a b where
  labelOptic = field "pad"
